<?php
define('CLI_SCRIPT', true);require(__DIR__.'/../../../config.php');
$options=getopt('', ['sessionid:','execute']);if(empty($options['sessionid'])){fwrite(STDERR,"Usage: php migrate_legacy_docspace.php --sessionid=123[,456] [--execute]\nDefault is dry-run.\n");exit(2);}$execute=array_key_exists('execute',$options);$ids=array_values(array_unique(array_filter(array_map('intval',preg_split('/[,;\s]+/',(string)$options['sessionid'])))));$fs=get_file_storage();$results=[];
foreach($ids as $sessionid){$r=['sessionid'=>$sessionid,'execute'=>$execute,'template'=>'none','snapshots'=>0,'status'=>''];try{$s=$DB->get_record('wsg_session',['id'=>$sessionid],'*',MUST_EXIST);$activity=$DB->get_record('worksheetgrader',['id'=>$s->worksheetgraderid],'*',MUST_EXIST);$cm=get_coursemodule_from_instance('worksheetgrader',$activity->id,$activity->course,false,MUST_EXIST);$ctx=context_module::instance($cm->id);$existing=$fs->get_area_files($ctx->id,'mod_worksheetgrader','officetemplate',$sessionid,'id',false);if($existing){$r['template']='already_migrated';$r['status']='ok';}else{$source=null;foreach($fs->get_area_files($ctx->id,'mod_worksheetgrader','docspacetemplate',$sessionid,'id',false) as $f){$source=$f;break;}if($source){$r['template']='local';if($execute){$new=$fs->create_file_from_storedfile(['contextid'=>$ctx->id,'component'=>'mod_worksheetgrader','filearea'=>'officetemplate','itemid'=>$sessionid,'filepath'=>'/','filename'=>$source->get_filename()],$source);$DB->update_record('wsg_session',(object)['id'=>$sessionid,'contentmode'=>'office','worksheetkind'=>'office','worksheethash'=>$new->get_contenthash(),'sourcefilename'=>$new->get_filename(),'migrationstatus'=>'migrated_local','timemodified'=>time()]);}$r['status']='ok';}else{$mapping=$DB->get_record('wsg_docspace',['sessionid'=>$sessionid,'teamid'=>0,'scope'=>'template']);if($mapping&&!empty($mapping->fileid)){$r['template']='remote';if($execute){$client=new \mod_worksheetgrader\docspace\client();$url=$client->get_presigned_uri((string)$mapping->fileid);$tmp=make_request_directory().'/legacy-'.bin2hex(random_bytes(4));$client->download_to_path($url,$tmp);if(!is_file($tmp)||filesize($tmp)<=0||filesize($tmp)>104857600)throw new moodle_exception('Invalid remote template size');$filename=clean_param((string)($mapping->filename?:'legacy.docx'),PARAM_FILE);$ext=strtolower(pathinfo($filename,PATHINFO_EXTENSION));if(!in_array($ext,['docx','xlsx','pptx','pdf'],true))throw new moodle_exception('Unsupported legacy Office extension');$new=$fs->create_file_from_pathname(['contextid'=>$ctx->id,'component'=>'mod_worksheetgrader','filearea'=>'officetemplate','itemid'=>$sessionid,'filepath'=>'/','filename'=>$filename],$tmp);$DB->update_record('wsg_session',(object)['id'=>$sessionid,'contentmode'=>'office','worksheetkind'=>$ext==='pdf'?'pdf':'office','worksheethash'=>$new->get_contenthash(),'sourcefilename'=>$new->get_filename(),'migrationstatus'=>'migrated_remote','timemodified'=>time()]);}$r['status']='ok';}else{$r['template']='unavailable';$r['status']='blocked';if($execute)$DB->update_record('wsg_session',(object)['id'=>$sessionid,'migrationstatus'=>'migration_blocked','timemodified'=>time()]);}}}
foreach($DB->get_records('wsg_attempt',['sessionid'=>$sessionid]) as $a){$old=null;foreach($fs->get_area_files($ctx->id,'mod_worksheetgrader','docspacesnapshot',$a->id,'id',false) as $f){$old=$f;break;}if(!$old)continue;$newfiles=$fs->get_area_files($ctx->id,'mod_worksheetgrader','officesubmission',$a->id,'id',false);if($newfiles)continue;$r['snapshots']++;if($execute)$fs->create_file_from_storedfile(['contextid'=>$ctx->id,'component'=>'mod_worksheetgrader','filearea'=>'officesubmission','itemid'=>$a->id,'filepath'=>'/','filename'=>$old->get_filename()],$old);}
}catch(Throwable $e){$r['status']='error';$r['error']=get_class($e).': '.$e->getMessage();}$results[]=$r;}
echo json_encode(['mode'=>$execute?'execute':'dry-run','mutation'=>$execute,'results'=>$results],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
